select max(trade_date)
  from sector_fund_flow_daily_snapshots
 where deleted_at is null
   and scope = #{scope}

   and trade_date <= #{maxTradeDate}

select 
  from sector_fund_flow_daily_snapshots
 where deleted_at is null
   and scope = #{scope}
   and trade_date = #{tradeDate}
 order by net desc nulls last, rank asc nulls last, sector_name asc
 limit #{limit}
